<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>'reports']); $labels=['page'=>'Páginas','project'=>'Projetos','article'=>'Artigos','highlight'=>'Destaques','testimonial'=>'Depoimentos','faq'=>'FAQ','media'=>'Mídia','proposal'=>'Propostas']; ?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">VISÃO GERAL</p><h2>Relatórios</h2><p>Indicadores calculados somente a partir dos registros persistidos.</p></div><a class="studio-button" href="?format=csv">Exportar CSV</a></header><section class="studio-report-grid"><?php foreach($counts as $key=>$count):?><article class="studio-panel"><small><?= $this->e($labels[$key]) ?></small><strong><?= $this->e((string)$count['total']) ?></strong><?php if($count['published']!==null):?><p><?= $this->e((string)$count['published']) ?> publicado(s)</p><?php else:?><p>registros</p><?php endif;?></article><?php endforeach;?></section><div class="studio-report-detail"><article class="studio-panel"><h2>Pipeline de propostas</h2><?php if($proposalStates===[]):?><p class="studio-empty">Sem propostas.</p><?php endif;?><ul class="studio-metric-list"><?php foreach($proposalStates as $row):?><li><span><?= $this->e($row['status']) ?></span><strong><?= (int)$row['total'] ?></strong></li><?php endforeach;?></ul></article><article class="studio-panel"><h2>Propostas por mês</h2><?php if($monthly===[]):?><p class="studio-empty">Sem dados no período.</p><?php endif;?><ul class="studio-metric-list"><?php foreach($monthly as $row):?><li><span><?= $this->e($row['period']) ?></span><strong><?= (int)$row['total'] ?></strong></li><?php endforeach;?></ul></article></div></section>
